import type { GameState } from '../engine/types'

export interface GlossaryEntry {
  slug: string
  title: string
  english: string
  definition: string
  aliases?: string[]
  related?: string[]
  board?: GameState
  boardCaption?: string
}

const position = (points: number[], bar: Partial<GameState['bar']> = {}): GameState => ({
  points,
  bar: { white: 0, black: 0, ...bar },
  off: { white: 0, black: 0 },
  turn: 'white',
  dice: [],
  diceUsed: [],
})

const empty = () => new Array(24).fill(0)
const board = (points: Record<number, number>, bar?: Partial<GameState['bar']>) => {
  const p = empty()
  for (const [index, count] of Object.entries(points)) p[Number(index)] = count
  return position(p, bar)
}

